-- Migração: Criação e Povoamento da Tabela Lideranca_SS (Secretaria da Saúde de Osasco)
-- Executar no SQL Editor do Supabase

CREATE TABLE IF NOT EXISTS public."Lideranca_SS" (
  id BIGSERIAL PRIMARY KEY,
  "Matrícula" BIGINT,
  "Nome Funcionário" TEXT,
  "Descrição Cargo" TEXT,
  "Sigla Cargo" TEXT,
  "Local Trabalho" BIGINT,
  "Descrição Local Trabalho" TEXT,
  "Símbolo Padrão Salário" TEXT,
  "Situação" TEXT DEFAULT 'Normal',
  "Descrição Categoria Funcional" TEXT,
  "Regime Trabalho" TEXT,
  "Data Admissão" TEXT,
  "CPF" TEXT,
  "RG" TEXT,
  "Nome Civil" TEXT,
  "Secretaria" TEXT DEFAULT '58.00.00',
  "Descrição Secretaria" TEXT DEFAULT 'SECRETARIA DA SAUDE',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Habilitar leitura pública anônima para a aplicação
ALTER TABLE public."Lideranca_SS" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir leitura publica em Lideranca_SS" ON public."Lideranca_SS";
CREATE POLICY "Permitir leitura publica em Lideranca_SS" ON public."Lideranca_SS" FOR SELECT USING (true);

-- Limpar registros anteriores e inserir a base oficial
TRUNCATE TABLE public."Lideranca_SS";

